// Validate the signed order and evaluate the Stage 1 gates.
// Gate policy lives in studex/managed-agents/03-CLIENT-FLOW.md.

const REQUIRED = [
  'client_name',
  'client_slug',
  'tier',
  'approver_name',
  'approver_email',
  'alternate_approver_name',
  'operator_name',
  'data_boundary'
];

const VALID_TIERS = ['managed_pilot', 'managed_operations', 'managed_team'];

const out = [];

for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const missing = REQUIRED.filter((f) => !body[f]);

  const workflows = Array.isArray(body.workflows) ? body.workflows : [];
  const forbidden = Array.isArray(body.forbidden_actions) ? body.forbidden_actions : [];

  const failures = [];
  if (missing.length) failures.push('missing fields: ' + missing.join(', '));
  if (!VALID_TIERS.includes(body.tier)) failures.push('tier must be one of ' + VALID_TIERS.join(', '));
  if (body.dpa_signed !== true) failures.push('data processing agreement is not signed');
  if (!workflows.length) failures.push('no agreed workflows supplied');
  if (!forbidden.length) failures.push('forbidden_actions is empty - the never-do list is mandatory');
  if (body.approver_name && body.approver_name === body.alternate_approver_name) {
    failures.push('approver and alternate approver must be different people');
  }

  // Tier drives how many agent identities get provisioned.
  const agentCountByTier = { managed_pilot: 1, managed_operations: 2, managed_team: 4 };

  out.push({
    json: {
      gates_passed: failures.length === 0,
      failures,
      client_name: body.client_name || null,
      client_slug: body.client_slug || null,
      tier: body.tier || null,
      agent_count: agentCountByTier[body.tier] || 1,
      workflows,
      forbidden_actions: forbidden,
      approver_name: body.approver_name || null,
      approver_email: body.approver_email || null,
      alternate_approver_name: body.alternate_approver_name || null,
      operator_name: body.operator_name || null,
      data_boundary: body.data_boundary || null,
      received_at: new Date().toISOString()
    }
  });
}

return out;

// Expand the order into one identity per agent and the standard channel set.
// One keypair per agent. Never share an identity between agents.

const order = $('Validate Order And Gates').first().json;
const community = $input.first().json;
const communityId = community.id || community.community_id || 'PENDING';

const ROLE_POOL = [
  { role: 'customer_care', persona: 'Answers approved product and policy questions.' },
  { role: 'sales_followup', persona: 'Drafts follow-up for review. Never sends unaided.' },
  { role: 'administration', persona: 'Prepares documents and tracks outstanding items.' },
  { role: 'reporting', persona: 'Assembles the weekly operating summary.' },
  { role: 'intake', persona: 'Captures and structures inbound enquiries.' }
];

const CHANNELS = [
  { name: 'general', purpose: 'Client and operator conversation' },
  { name: 'agent-worklog', purpose: 'Agents post what they did' },
  { name: 'approvals', purpose: 'External actions wait here for a named human' },
  { name: 'knowledge', purpose: 'Requests to add or correct the knowledge pack' },
  { name: 'exceptions', purpose: 'Anything the agents could not handle' },
  { name: 'review', purpose: 'Weekly and monthly operating summaries' }
];

const agents = ROLE_POOL.slice(0, order.agent_count).map((r, i) => ({
  agent_name: order.client_slug + '-' + r.role,
  role: r.role,
  persona: r.persona,
  sequence: i + 1,
  // Least privilege by default. Widen only with written client agreement.
  scopes: ['read:knowledge', 'write:agent-worklog', 'propose:approvals'],
  forbidden_actions: order.forbidden_actions
}));

return [{
  json: {
    community_id: communityId,
    client_name: order.client_name,
    client_slug: order.client_slug,
    tier: order.tier,
    operator_name: order.operator_name,
    approver_name: order.approver_name,
    alternate_approver_name: order.alternate_approver_name,
    data_boundary: order.data_boundary,
    workflows: order.workflows,
    forbidden_actions: order.forbidden_actions,
    agents,
    channels: CHANNELS
  }
}];
